 "content": "def transform(grid):
    """Extend each diagonal run of matching non-background markers."""
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    colors = {value for row in grid for value in row if value != background}
    for color in colors:
        points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color]
        # Each adjacent diagonal pair defines the direction of a ray.
        rays = set()
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if abs(r2 - r1) == 1 and abs(c2 - c1) == 1:
                    dr = 1 if r2 > r1 else -1
                    dc = 1 if c2 > c1 else -1
                    rays.add((r1, c1, dr, dc))

        for r1, c1, dr, dc in rays:
            aligned = [p for p in points if (p[0] - r1) * dc == (p[1] - c1) * dr]
            r, c = max(aligned, key=lambda p: (p[0] - r1) * dr)
            while 0 <= r + dr < height and 0 <= c + dc < width:
                nr, nc = r + dr, c + dc
                if grid[nr][nc] != background:
                    break
                r, c = nr, nc
                out[r][c] = color
    return out
