    """Extend each diagonal run of matching colors through empty cells."""
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # A same-color diagonal neighbor pair defines a line. Extend both ends of
    # each such run until the edge or the first occupied cell.
    for color in counts:
        if color == background:
            continue
        points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color]
        for r, c in points:
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < height and 0 <= nc < width) or grid[nr][nc] != color:
                    continue
                # Extend backward from the first marker.
                rr, cc = r, c
                while 0 <= rr - dr < height and 0 <= cc - dc < width:
                    rr, cc = rr - dr, cc - dc
                    if grid[rr][cc] != background:
                        break
                    out[rr][cc] = color
                # Extend forward from the second marker.
                rr, cc = nr, nc
                while 0 <= rr + dr < height and 0 <= cc + dc < width:
                    rr, cc = rr + dr, cc + dc
                    if grid[rr][cc] != background:
                        break
                    out[rr][cc] = color
    return out
